import { useCallback, useEffect, useRef, useState } from 'react';
import { flushSync } from 'react-dom';
import { readStoredTheme, rememberTheme } from '../utils/consent';

const getSystemPreference = () => {
  if (typeof window === 'undefined' || !window.matchMedia) return 'light';
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
};

// The inline script in index.html picks the first theme before React boots;
// later pages read the window globals so a manual toggle survives client-side
// navigation without being written anywhere.
const getInitialTheme = () => {
  if (typeof window === 'undefined') return 'light';
  if (typeof window.__INITIAL_THEME__ === 'string') return window.__INITIAL_THEME__;
  return readStoredTheme() || getSystemPreference();
};

const getInitialManual = () => {
  if (typeof window === 'undefined') return false;
  if (typeof window.__HAS_MANUAL_THEME__ === 'boolean') return window.__HAS_MANUAL_THEME__;
  return readStoredTheme() !== null;
};

/**
 * Light/dark theme shared by every page. Follows the system setting until the
 * visitor toggles; a toggle is only persisted with their consent (see
 * utils/consent.js), otherwise it lasts until the page reloads.
 */
export default function useSiteTheme() {
  const [theme, setTheme] = useState(getInitialTheme);
  const [hasManualPreference, setHasManualPreference] = useState(getInitialManual);
  const themeRef = useRef(theme);
  themeRef.current = theme;

  useEffect(() => {
    if (typeof document === 'undefined') return;
    const root = document.documentElement;
    root.classList.toggle('dark', theme === 'dark');
    root.dataset.theme = theme;
    root.style.colorScheme = theme;
    window.__INITIAL_THEME__ = theme;
    window.__HAS_MANUAL_THEME__ = hasManualPreference;
  }, [theme, hasManualPreference]);

  useEffect(() => {
    if (typeof window === 'undefined' || hasManualPreference) return;
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    const sync = (e) => setTheme(e.matches ? 'dark' : 'light');
    setTheme(mq.matches ? 'dark' : 'light');
    mq.addEventListener('change', sync);
    return () => mq.removeEventListener('change', sync);
  }, [hasManualPreference]);

  const toggleTheme = useCallback((event) => {
    let next;
    const apply = () => {
      flushSync(() => {
        next = themeRef.current === 'dark' ? 'light' : 'dark';
        setTheme(next);
        setHasManualPreference(true);
      });
    };
    const finish = () => rememberTheme(next);

    if (!document.startViewTransition || !event) { apply(); finish(); return; }
    const { clientX: x, clientY: y } = event;
    const r = Math.hypot(Math.max(x, innerWidth - x), Math.max(y, innerHeight - y));
    const transition = document.startViewTransition(apply);
    transition.ready.then(() => {
      document.documentElement.animate(
        { clipPath: [`circle(0px at ${x}px ${y}px)`, `circle(${r}px at ${x}px ${y}px)`] },
        { duration: 500, easing: 'ease-in-out', pseudoElement: '::view-transition-new(root)' }
      );
    }).catch(() => {});
    transition.finished.then(finish, finish);
  }, []);

  return { theme, toggleTheme };
}
